"""V2 Phase B (owner decisions D1, D2, D5, 2026-11-17): the working sketch of an order and its revisions.

* `sketch_revisions`: every state of the customer's working sketch of an order (DRAFT), generated by the engine or changed by
  the customer / the assistant / the Staff through the geometry engine. Nothing is updated in place; `parent_id` links the
  history (undo moves the order's cursor to the parent, redo to the latest child). The geometry itself is a `vhrs-sketch/2`
  file in object storage (`geometry_uri`, SHA-256 in `geometry_hash`): polylines in mm with stable ids (D5: polyline is the
  canonical format). `inputs_hash` is the hash of what the geometry was built from (text, template, size, layout, images,
  paper size...), so the API can say the sketch is out of date after the customer changed the content. `operation` is the
  structured edit that produced the revision (never free coordinates from a language model).
* `orders.current_sketch_revision_id`: the cursor.
* `sketches.source_revision_id`: the customer's revision an official version was taken from (D2: when the Staff take the
  order, v1 is exactly that geometry, not a new generation), so "the Staff received what the customer approved" is checkable.

Rows go with their order (ON DELETE CASCADE); an account deletion keeps the row and clears `actor_id`.
Additive only: no existing row changes. Rollback: `alembic downgrade 0022`.

Revision ID: 0023
Revises: 0022
"""
from alembic import op

revision = "0023"
down_revision = "0022"
branch_labels = None
depends_on = None

UPGRADE = [
    """CREATE TABLE IF NOT EXISTS sketch_revisions (
        id             BIGSERIAL PRIMARY KEY,
        order_id       BIGINT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,
        parent_id      BIGINT REFERENCES sketch_revisions(id) ON DELETE CASCADE,
        seq            INTEGER NOT NULL CHECK (seq >= 1),
        author         VARCHAR(10) NOT NULL CHECK (author IN ('ENGINE', 'CUSTOMER', 'AI', 'STAFF')),
        actor_id       BIGINT REFERENCES accounts(id) ON DELETE SET NULL,
        tool_name      VARCHAR(40),
        provider       VARCHAR(20),
        model          VARCHAR(80),
        note           VARCHAR(300),
        operation      JSONB,
        geometry_uri   TEXT NOT NULL,
        geometry_hash  CHAR(64) NOT NULL,
        inputs_hash    CHAR(64),
        metrics        JSONB,
        validation     JSONB,
        created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
        UNIQUE (order_id, seq),
        CONSTRAINT chk_sketch_rev_tool CHECK (author <> 'AI' OR tool_name IS NOT NULL)
    )""",
    "CREATE INDEX IF NOT EXISTS ix_sketch_revisions_order ON sketch_revisions (order_id, seq)",
    "ALTER TABLE orders ADD COLUMN IF NOT EXISTS current_sketch_revision_id BIGINT",
    """DO $$ BEGIN
        IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_orders_current_sketch_revision') THEN
            ALTER TABLE orders ADD CONSTRAINT fk_orders_current_sketch_revision
                FOREIGN KEY (current_sketch_revision_id) REFERENCES sketch_revisions(id) ON DELETE SET NULL;
        END IF;
    END $$""",
    "ALTER TABLE sketches ADD COLUMN IF NOT EXISTS source_revision_id BIGINT",
    """DO $$ BEGIN
        IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_sketches_source_revision') THEN
            ALTER TABLE sketches ADD CONSTRAINT fk_sketches_source_revision
                FOREIGN KEY (source_revision_id) REFERENCES sketch_revisions(id) ON DELETE SET NULL;
        END IF;
    END $$""",
]

DOWNGRADE = [
    "ALTER TABLE sketches DROP CONSTRAINT IF EXISTS fk_sketches_source_revision",
    "ALTER TABLE sketches DROP COLUMN IF EXISTS source_revision_id",
    "ALTER TABLE orders DROP CONSTRAINT IF EXISTS fk_orders_current_sketch_revision",
    "ALTER TABLE orders DROP COLUMN IF EXISTS current_sketch_revision_id",
    "DROP TABLE IF EXISTS sketch_revisions",
]


def upgrade() -> None:
    for stmt in UPGRADE:
        op.execute(stmt)


def downgrade() -> None:
    for stmt in DOWNGRADE:
        op.execute(stmt)
